                                    {
                                        <div class="error-message">@passwordError</div>
                                    }
                                    <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-item security-toggle">
                            <label class="toggle-label">
                                <span>Two-Factor Authentication</span>
                                <input type="checkbox" @bind="editTwoFactor" />
                                <span class="toggle-switch"></span>
                            </label>
                            <span class="status-indicator @(editTwoFactor ? "status-enabled" : "status-disabled")">
                                @(editTwoFactor ? "Enabled" : "Disabled")
                            </span>
                        </div>

                        @if (security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-wrapper">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in security.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@FormatLastActive(session.LastActive)</td>
                                            <td>
                                                @if (session.Id != security.Sessions.FirstOrDefault()?.Id)
                                                {
                                                    <button class="btn-danger-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                }
                                                else
                                                {
                                                    <span class="current-badge">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>

                    @if (showRevokeConfirmation)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal-dialog" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>

                <div class="appearance-layout">
                    <div class="appearance-controls">
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' />
                                    <span>Light</span>
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' />
                                    <span>Small</span>
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Language</label>
                            <select @bind="editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <input type="checkbox" @bind="editCompactMode" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>

                    <div class="appearance-preview @GetPreviewClasses()">
                        <h4>Live Preview</h4>
                        <div class="preview-card">
                            <div class="preview-header">Sample Header</div>
                            <p class="preview-text">This is how your content will look with the selected settings.</p>
                            <div class="preview-actions">
                                <span class="preview-btn">Button</span>
                                <span class="preview-link">Link</span>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
        }
    </main>
</div>

