        display: flex;
        overflow-x: auto;
        position: static;
    }

    .settings-sidebar li {
        white-space: nowrap;
    }

    .profile-layout {
        grid-template-columns: 1fr;
    }

    .appearance-layout {
        grid-template-columns: 1fr;
    }
}

